            sed -e 's/-L/:/g' -e 's/ //g'`"                                     \
        $(RUNSERIAL) ./H5detect$(EXEEXT)  $@  ||                                \
            (test $$HDF5_Make_Ignore && echo "*** Error ignored") ||            \
            ($(RM) $@ ; exit 1)

